def has_triangle_property(subset):
    subset_sorted = sorted(subset)
    for i in range(len(subset_sorted) - 2):
        if subset_sorted[i] + subset_sorted[i+1] <= subset_sorted[i+2]:
            return False
    return True

def find_largest_n():
    for n in range(23, 3, -1):
        if all(has_triangle_property(subset) for subset in combinations(range(4, n+1), 10)):
